import Foundation

/// Scheduled-task wire models. Mirrors `daemon/src/types/api.ts`.

public struct SchedulePresetDto: Decodable, Equatable, Sendable {
    public let preset: String
    public let time: String?
    public let days: [Int]?
    public let every: Int?
}

public struct ScheduleDto: Decodable, Equatable, Sendable {
    public let cron: String
    public let timezone: String
    public let preset: SchedulePresetDto?
    /// Human-readable summary generated by the daemon (e.g. “每天 09:00”).
    public let label: String
}

public struct ScheduledTaskDto: Decodable, Equatable, Sendable {
    public let id: String
    public let name: String
    /// `ai` | `command`
    public let type: String
    /// `existing` | `new` | `internal`
    public let sessionMode: String
    public let sessionId: String?
    public let sessionTitle: String?
    public let workspaceId: String
    public let runtime: String
    public let prompt: String?
    public let command: String?
    public let permissionMode: String
    public let schedule: ScheduleDto
    public let nextRunAt: Int64?
    public let lastFireAt: Int64?
    public let lastRunAt: Int64?
    /// never | running | succeeded | failed | cancelled | interrupted | skipped_busy | skipped_missed
    public let lastStatus: String
    public let lastError: String?
    public let lastRunId: String?
    public let runCount: Int
    public let enabled: Bool
    public let disabledReason: String?
    /// `user` | `mcp`
    public let createdBy: String
    public let createdAt: Int64
    public let updatedAt: Int64
}

public struct ScheduledTasksResponse: Decodable, Equatable, Sendable {
    public let tasks: [ScheduledTaskDto]

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        tasks = try container.decodeIfPresent([ScheduledTaskDto].self, forKey: .tasks) ?? []
    }

    private enum CodingKeys: String, CodingKey {
        case tasks
    }
}

public struct ScheduledTaskDetailResponse: Decodable, Equatable, Sendable {
    public let task: ScheduledTaskDto
    public let runs: [RunDto]

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        task = try container.decode(ScheduledTaskDto.self, forKey: .task)
        runs = try container.decodeIfPresent([RunDto].self, forKey: .runs) ?? []
    }

    private enum CodingKeys: String, CodingKey {
        case task, runs
    }
}

public struct ScheduledTaskResponse: Decodable, Equatable, Sendable {
    public let ok: Bool
    public let task: ScheduledTaskDto
}

public struct RunNowResponse: Decodable, Equatable, Sendable {
    public let ok: Bool
    public let runId: String
    public let sessionId: String
}

public struct DeletedScheduledTaskResponse: Decodable, Equatable, Sendable {
    public let ok: Bool
    public let id: String
}

public struct TaskConfigSessionResponse: Decodable, Equatable, Sendable {
    public let ok: Bool
    public let sessionId: String
    /// The run that just started; nil when the session already had one.
    public let runId: String?
    public let busy: Bool

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        ok = try container.decodeIfPresent(Bool.self, forKey: .ok) ?? true
        sessionId = try container.decode(String.self, forKey: .sessionId)
        runId = try container.decodeIfPresent(String.self, forKey: .runId)
        busy = try container.decodeIfPresent(Bool.self, forKey: .busy) ?? false
    }

    private enum CodingKeys: String, CodingKey {
        case ok, sessionId, runId, busy
    }
}

// MARK: - Requests

public struct SchedulePresetInput: Encodable, Sendable {
    public let preset: String
    public let time: String?
    public let days: [Int]?
    public let every: Int?

    public init(preset: String, time: String? = nil, days: [Int]? = nil, every: Int? = nil) {
        self.preset = preset
        self.time = time
        self.days = days
        self.every = every
    }
}

public struct ScheduledTaskTargetInput: Encodable, Sendable {
    public let mode: String
    public let sessionId: String?
    public let workspaceId: String?
    public let runtime: String?

    public init(mode: String, sessionId: String? = nil, workspaceId: String? = nil, runtime: String? = nil) {
        self.mode = mode
        self.sessionId = sessionId
        self.workspaceId = workspaceId
        self.runtime = runtime
    }
}

public struct CreateScheduledTaskRequest: Encodable, Sendable {
    public let name: String
    public let type: String
    public let prompt: String?
    public let command: String?
    public let target: ScheduledTaskTargetInput
    public let schedule: SchedulePresetInput

    public init(
        name: String,
        type: String,
        prompt: String?,
        command: String?,
        target: ScheduledTaskTargetInput,
        schedule: SchedulePresetInput
    ) {
        self.name = name
        self.type = type
        self.prompt = prompt
        self.command = command
        self.target = target
        self.schedule = schedule
    }
}

public struct UpdateScheduledTaskRequest: Encodable, Sendable {
    public let name: String?
    public let prompt: String?
    public let command: String?
    public let enabled: Bool?
    public let schedule: SchedulePresetInput?

    public init(
        name: String? = nil,
        prompt: String? = nil,
        command: String? = nil,
        enabled: Bool? = nil,
        schedule: SchedulePresetInput? = nil
    ) {
        self.name = name
        self.prompt = prompt
        self.command = command
        self.enabled = enabled
        self.schedule = schedule
    }
}
